import unittest
from unittest import mock

from pylint.config._pylint_config.generate_command import handle_generate_command


class ArgParserStub:
    def __init__(self):
        self._subparsers = {}

    def print_help(self, file=None):
        pass


class ConfigStub:
    def __init__(self, interactive):
        self.interactive = interactive

    def __getattr__(self, name):
        m = mock.Mock(name=name)
        setattr(self, name, m)
        return m


class LinterStubInteractive:
    def __init__(self):
        self.config = ConfigStub(True)


class LinterStubNonInteractive:
    def __init__(self):
        self.config = ConfigStub(False)
        self._arg_parser = ArgParserStub()


class TestHandleGenerateCommand(unittest.TestCase):
    @mock.patch("builtins.input", return_value="y")
    def test_handle_generate_command_interactive_calls_generation_and_returns_0(self, _input):
        linter = LinterStubInteractive()

        ret = handle_generate_command(linter)

        self.assertEqual(ret, 0)

        # Ensure at least one of the potential generation methods was invoked
        gen_names = ["generate_pylintrc", "generate_config", "generate"]
        called = False
        for name in gen_names:
            if hasattr(linter.config, name):
                if getattr(linter.config, name).call_count > 0:
                    called = True
                    break
        self.assertTrue(called)

        # Ensure linter state remains unchanged
        self.assertTrue(linter.config.interactive)

    def test_handle_generate_command_non_interactive_prints_help_and_returns_32(self):
        linter = LinterStubNonInteractive()

        with mock.patch("builtins.print") as mock_print:
            ret = handle_generate_command(linter)

        self.assertEqual(ret, 32)
        mock_print.assert_called()

        # Ensure no generation function was invoked
        gen_names = ["generate_pylintrc", "generate_config", "generate"]
        for name in gen_names:
            if hasattr(linter.config, name):
                self.assertEqual(getattr(linter.config, name).call_count, 0)


if __name__ == "__main__":
    unittest.main()

