    def _build_node_with_locals(self, locals_dict, methods=None):
        class Node:
            pass

        node = Node()
        node.locals = locals_dict
        if methods is None:
            methods = []
        node.mymethods = lambda: methods
        return node

    def test_warns_when_eq_without_hash(self):
        node = self._build_node_with_locals({'__eq__': 'present'}, methods=[])
        with mock.patch.object(self.checker, 'add_message') as mock_add:
            self.checker.visit_classdef(node)
            mock_add.assert_called_once_with('W1641', node=node)

    def test_no_warn_when_hash_present_in_methods(self):
        node = self._build_node_with_locals({'__eq__': 'present'}, methods=[DummyMethod('__hash__')])
        with mock.patch.object(self.checker, 'add_message') as mock_add:
            self.checker.visit_classdef(node)
            mock_add.assert_not_called()

    def test_no_warn_when_eq_not_present(self):
        node = self._build_node_with_locals({}, methods=[])
        with mock.patch.object(self.checker, 'add_message') as mock_add:
            self.checker.visit_classdef(node)
            mock_add.assert_not_called()


