            if not hasattr(self, "_calls"):
                self._calls = {"set_status": [], "register_by_id": []}
            self._calls["set_status"].append((msgid, scope, status, line, enable, kwargs))
            # Update internal state to reflect enabling for test verification
            if enable is not None:
