        def _register_by_id_managed_msg(self, msgid, scope=None, line=None, **kwargs):
            if not hasattr(self, "_calls"):
                self._calls = {"set_status": [], "register_by_id": []}
            self._calls["register_by_id"].append((msgid, scope, line, kwargs))

        import types
        handler._set_msg_status = types.MethodType(_set_msg_status, handler)
        handler._register_by_id_managed_msg = types.MethodType(_register_by_id_managed_msg, handler)
