        handler.enable("MSG_A", scope="package", line=None, ignore_unknown=False)

        # Checks that the message state is updated to True (enabled)
        self.assertIn("MSG_A", handler._msgs_state)
        self.assertTrue(handler._msgs_state["MSG_A"])

        # Ensure that the hooked methods were called
        self.assertTrue(hasattr(handler, "_calls"))
        self.assertGreaterEqual(len(handler._calls.get("set_status", [])), 1)
        self.assertGreaterEqual(len(handler._calls.get("register_by_id", [])), 1)

    def test_enable_unknown_msg_behaviors(self):
        handler = self._create_handler()

        # Unknown message with ignore_unknown=False should raise ValueError
        with self.assertRaises(ValueError):
            handler.enable("UNKNOWN_MSG", scope="package", line=None, ignore_unknown=False)

        # Unknown message with ignore_unknown=True should not raise and should not add message state
        try:
            handler.enable("UNKNOWN_MSG", scope="package", line=None, ignore_unknown=True)
        except Exception as exc:
            self.fail(f"enable with ignore_unknown=True raised an exception: {exc}")

