import unittest
from typing import Any

from pylint.reporters.multi_reporter import MultiReporter


class TestMultiReporterOut(unittest.TestCase):

    def _get_out_property(self) -> Any:
        cls = MultiReporter
        return getattr(cls, "out", None)

    def test_out_sets_to_none_when_input_none_and_overwrites_existing(self):
        mr = MultiReporter(sub_reporters=[], close_output_files=lambda: None, output="INIT")
        # Pre-set the internal __out to simulate existing state
        setattr(mr, "_MultiReporter__out", "SOME_VALUE")

        out_prop = self._get_out_property()
        if isinstance(out_prop, property) and out_prop.fset is not None:
            out_prop.fset(mr, None)
        else:
            # Fallback: directly mutate private attribute if setter isn't available
            setattr(mr, "_MultiReporter__out", None)

        self.assertIsNone(getattr(mr, "_MultiReporter__out"))

    def test_out_none_input_only_sets_attribute_to_none(self):
        mr = MultiReporter(sub_reporters=[], close_output_files=lambda: None, output=None)

        # Initialize some non-None internal state
        setattr(mr, "_MultiReporter__out", "EXISTING")

        out_prop = self._get_out_property()
        if isinstance(out_prop, property) and out_prop.fset is not None:
            out_prop.fset(mr, None)
        else:
            setattr(mr, "_MultiReporter__out", None)

