        graph = {
            'A': {'B'},
            'B': {'A'},
            'C': {'D'},
            'D': {'E'},
            'E': {'C'}
        }
        cycles = get_cycles(graph, vertices=['A'])
        self.assertIsInstance(cycles, list)
        self.assertEqual(len(cycles), 1)
        self.assertTrue(set(cycles[0]) in [ {'A', 'B'} ])

