        cycles = get_cycles(graph)
        self.assertIsInstance(cycles, list)
        self.assertGreaterEqual(len(cycles), 1)
        found = any(set(cycle) == {'A', 'B', 'C'} for cycle in cycles)
        self.assertTrue(found, f"No cycle containing A, B, and C found in {cycles}")

    def test_no_cycles_returns_empty(self):
        graph = {
            'A': {'B'},
            'B': {'C'},
            'C': {'D'},
            'D': set()
        }
        cycles = get_cycles(graph)
        self.assertIsInstance(cycles, list)
        self.assertEqual(len(cycles), 0)

    def test_multiple_cycles_detected(self):
        graph = {
            'A': {'B'},
            'B': {'A'},
            'C': {'D'},
            'D': {'C'}
        }
        cycles = get_cycles(graph)
        self.assertIsInstance(cycles, list)
        self.assertGreaterEqual(len(cycles), 2)
        sets = [set(c) for c in cycles]
        self.assertIn({'A', 'B'}, sets)
        self.assertIn({'C', 'D'}, sets)

    def test_vertices_filtering(self):
        graph = {
            'A': {'B'},
            'B': {'A'},
            'C': {'D'},
            'D': {'E'},
            'E': {'C'}
        }
        cycles = get_cycles(graph, vertices=['A'])
        self.assertIsInstance(cycles, list)
        self.assertEqual(len(cycles), 1)
        self.assertTrue(set(cycles[0]) in [ {'A', 'B'} ])

    def test_input_unchanged(self):
        graph = {
            'A': {'B'},
            'B': {'A'},
            'C': {'D'},
            'D': {'E'},
            'E': {'C'}
        }
        original = deepcopy(graph)
        _ = get_cycles(graph)
        self.assertEqual(graph, original)


if __name__ == '__main__':
    unittest.main()

